+impl bincode::Encode for ServicePayload {
+    fn encode<E: bincode::enc::Encoder>(&self, encoder: &mut E) -> Result<(), bincode::error::EncodeError> {
+        self.version.encode(encoder)?;
+        self.pro_tx_hash.encode(encoder)
+    }
+}
+
+#[cfg(feature = "bincode")]
+impl<C> bincode::Decode<C> for ServicePayload {
+    fn decode<D: bincode::de::Decoder<Context = C>>(decoder: &mut D) -> Result<Self, bincode::error::DecodeError> {
+        use bincode::Decode;
+        Ok(Self { version: Decode::decode(decoder)?, pro_tx_hash: Decode::decode(decoder)? })
+    }
